(window.LADDER_CARDS=window.LADDER_CARDS||{})["4k"]=[{"q": "On rung 4, a set having n members comes down to what?", "a": "X is matched with n", "w": ["X was counted to n", "X is part of n", "n is part of X"], "why": "4k2: having n members."}, {"q": "X is matched with Y, and Y with Z. What follows?", "a": "X is matched with Z", "w": ["Y is matched with nothing", "X and Z are equal", "nothing"], "why": "The chain technique for matchings."}, {"q": "A and B have no member in common, with p and b members. How many has A ∪ B?", "a": "p + b", "w": ["p · b", "p + b − 1", "the larger of p and b"], "why": "4k5: separate piles add."}, {"q": "A choice of p things, then for each one a choice of b. How many pairs of choices?", "a": "p · b", "w": ["p + b", "pᵇ", "bᵖ"], "why": "4k6: choices in stages multiply."}, {"q": "0 + 1 + ⋯ + n.", "a": "n · (n + 1) / 2", "w": ["n²/2", "n · (n − 1)", "2ⁿ"], "why": "4k8: the doubled sum."}, {"q": "X has n members and Y has m. How many functions from X to Y?", "a": "mⁿ", "w": ["nᵐ", "m · n", "m + n"], "why": "4k9: counting functions."}, {"q": "A set with n members. How many parts does it have?", "a": "2ⁿ", "w": ["n²", "n!", "2n"], "why": "4k10: each member in or out."}, {"q": "A set with n members. How many arrangements?", "a": "n!", "w": ["2ⁿ", "nⁿ", "n²"], "why": "4k11: arrangements and factorials."}, {"q": "An entry of the choosing table after the start of its row is…", "a": "the entry above it plus the one before that", "w": ["the entry above it, doubled", "the row number times the entry before", "1, always"], "why": "4k12: the table’s technique."}, {"q": "Row n of the choosing table counts the terms of what?", "a": "a sum of two numbers raised to the n", "w": ["n factorial", "the parts of n with n members", "the functions from n to 2"], "why": "4k15: a sum raised to a power."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["4l"]=[{"q": "Writing an algorithm down names which five parts?", "a": "a state, a start, a stop test, a move, an output", "w": ["a start, an end, a loop, a guess, a count", "an input, a table, a technique, a proof, a stop", "a case, a box, a row, a margin, a mark"], "why": "4l1: a recipe, part by part."}, {"q": "How many proofs does a recipe for answers need?", "a": "two: that it stops, and that the answer is right", "w": ["one: that it stops", "one: that the answer is right", "none, if it is short"], "why": "The gesture of 4l."}, {"q": "A counting number read off the state is smaller after every move. What follows?", "a": "every run stops", "w": ["the answer is right", "the run never stops", "the number is the answer"], "why": "4l2: why it stops."}, {"q": "A statement true at the start and kept by every move. What follows?", "a": "it is true at the stop", "w": ["the run stops", "it is false at the stop", "it is the stop test"], "why": "4l3: why the answer is right."}, {"q": "Finding an algorithm’s invariant is finding what?", "a": "what its moves never change", "w": ["how many moves it takes", "where it stops", "its fastest move"], "why": "4l4."}, {"q": "The falling number that proves a run stops. Its accepted name?", "a": "a variant, or termination measure", "w": ["a loop invariant", "a trace", "an output"], "why": "The cellar."}, {"q": "An algorithm that is right whenever it stops, but may not stop. What is it called?", "a": "partially correct", "w": ["totally correct", "effective", "terminating"], "why": "Totally correct needs both proofs."}, {"q": "Between moves of a written algorithm, what else may happen?", "a": "nothing", "w": ["a guess", "a new start", "a check by hand"], "why": "Writing it down is naming its five parts."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["4m"]=[{"q": "2 + 3 = 5. Of what does it hold?", "a": "apples, stones and days alike", "w": ["apples only", "numbers only, never things", "things that are the same size"], "why": "4m1: the operator forgets the things."}, {"q": "Why does one proof about adding cover every pile of anything?", "a": "adding works on the count, not the things", "w": ["every pile was checked by hand", "all piles are made of the same thing", "it does not cover every pile"], "why": "The things have been taken out."}, {"q": "An operator that ignores the things. Of what kind of thing does it hold?", "a": "every kind", "w": ["no kind", "one kind only", "the kind it was proved on"], "why": "Anexact, yet rigorous: the process that forgets."}, {"q": "4d defines by repeating, 4f builds adding, 4g builds multiplying. How do these processes fit?", "a": "each plugs into the next", "w": ["each stands alone", "only the last is proved", "multiplying comes first"], "why": "4m2: processes that plug together."}, {"q": "How do the things come back, after the process?", "a": "as measurements", "w": ["they never come back", "as new operators", "as cases"], "why": "4m3: bringing the things back."}, {"q": "Which step matches a pile of things with a number, so the number can go through the processes?", "a": "4k’s counting", "w": ["4l’s stop test", "4j’s remainders", "3b’s possible"], "why": "4m3."}, {"q": "Working with operations while ignoring what they act on. Its accepted name?", "a": "abstraction", "w": ["induction", "division", "composition"], "why": "The cellar."}, {"q": "The plug-together structure of operations is what which field studies?", "a": "algebra", "w": ["geometry", "statistics", "logic alone"], "why": "The cellar."}];
