(function(C){C["4c"]=(C["4c"]||[]).concat([{"q": "The step is proved: for any number n, if φ(n) then φ(S(n)). The base φ(0) was never checked. What stands?", "a": "nothing yet: the step only carries what the base hands it", "w": ["φ of every number", "φ(0)", "φ of every number but 0"], "why": "The dominoes: the spacing is the step and the push is the base. With no push, no domino falls."}, {"q": "φ(n): every member of n is a part of n. Which line is the induction hypothesis, supposed inside the step?", "a": "every member of n is a part of n", "w": ["every member of S(0) is a part of S(0)", "every member of S(n) is a part of S(n)", "every member of 0 is a part of 0"], "why": "The base is φ(0). The step is ∀n ∈ ℕ (φ(n) ⇒ φ(S(n))): inside it φ(n) is supposed, the induction hypothesis, and φ(S(n)) is what must be reached."}, {"q": "A proof by induction checks φ(0), φ(1), φ(2), φ(3) and φ(4), and stops. What is missing?", "a": "the step: one argument from φ(n) to φ(S(n)), for any number n", "w": ["the base", "the case φ(5)", "nothing: five cases are enough"], "why": "Cases looked at are not the step. The step is one argument, with n any number, and the base hands it its first case."}, {"q": "φ(n): n ≠ S(n). Which line is the base?", "a": "0 ≠ S(0)", "w": ["n ≠ S(n)", "S(0) ≠ S(S(0))", "S(n) ≠ S(S(n))"], "why": "The base is φ(0). The step is ∀n ∈ ℕ (φ(n) ⇒ φ(S(n))): inside it φ(n) is supposed, the induction hypothesis, and φ(S(n)) is what must be reached."}, {"q": "φ(n): 0 ⊆ n. Which line must the step reach?", "a": "0 ⊆ S(n)", "w": ["0 ⊆ 0", "0 ⊆ S(0)", "0 ⊆ n"], "why": "The base is φ(0). The step is ∀n ∈ ℕ (φ(n) ⇒ φ(S(n))): inside it φ(n) is supposed, the induction hypothesis, and φ(S(n)) is what must be reached."}, {"q": "A step never uses its hypothesis: it reaches φ(S(n)) whatever is so of n. Is the induction still sound?", "a": "yes: a step that does not need its hypothesis is still a step", "w": ["no: then the base is not needed", "only if φ(0) fails", "no: the hypothesis must be used"], "why": "Zero-or-a-next is proved this way: S(n) is the next one after n, whatever is so of n. The if from φ(n) to φ(S(n)) holds all the same."}, {"q": "Inside the step, φ(n) is supposed. Is that supposing what you want to prove?", "a": "no: it supposes φ of one number n, to reach φ of its next one", "w": ["yes, but the base repairs it", "no: φ(n) is a given", "yes, and so induction is a circle"], "why": "The induction hypothesis is φ(n) for one number n, supposed in a box. What is wanted is φ of every number. The box reports only the if from n to S(n)."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
